INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66079003', 66079003, 'analyze_legacy', 'Perpustakaan Nasional Republik Indonesia', 'central', 'PERPUSTAKAAN NASIONAL RI JAKARTA', 'Pembuatan Alih Wahana Naskah Kuno Nusantara', 'Jasa Lainnya', 'Penunjukan Langsung', 'DKI Jakarta, Jakarta Pusat (Kota)', 1850000000, 'March 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '100 naskah', 'Alih wahana merupakan karya transformasi dalam bentuk buku bergambar dan komik untuk mempermudah pembaca masa kini memahami karya sastra masa lalu tanpa menghilangkan aspek-aspek estetika yang ada dalam naskah Nusantara. Seperti yang telah diketahui bahwa aksara-aksara yang terdapat dalam naskah kuno nusantara sangat beraneka ragam, mulai dari Bali, Batak, Jawa, Jawi, Lontara, Lampung, Pegon, dan lain sebagainya. Banyak dari aksara-aksara tersebut kini sudah tidak dapat dibaca oleh masyarakat pendukungnya dan masyarakat umum. Oleh karena itu dibutuhkan proses alih wahana teks dalam naskah-naskah tersebut supaya informasi yang terdapat di dalamnya tidak hilang dan dapat dimanfaatkan oleh masyarakat umum. Kegiatan Alih Wahana Naskah Kuno merupakan upaya untuk menyediakan dan menyampaikan informasi, pengetahuan, dan nilai-nilai kehidupan yang terdapat dalam naskah kuno kepada masyarakat khususnya anak-anak melalui buku cerita anak. Proses penyediaan dan penyampaian informasi, pengetahuan, dan nilai-nilai kehidupan dalam naskah kuno yang ditulis tangan dengan menggunakan bahasa dan aksara daerah dilakukan melalui proses kajian yang dilakukan oleh peneliti lalu disusun dalam cerita anak yang lebih menarik disertai dengan ilustrasi. Contoh: buku cerita bergambar dan komik dengan berdasarkan isi naskah kuno. Hasil kegiatan akan diterbitkan dan disebarluaskan kepada anak-anak agar pengetahuan dan kisah-kisah menarik dari naskah kuno Nusantara dapat diketahui oleh anak- anak sebagai sarana penguatan karakter dan pengembangan kreativitas anak.', 'a. Bahan pustaka yang dialih-wahanakan adalah naskah kuno nusantara. Dokumen ini telah ditandatangani secara elektronik menggunakan sertifikat elektronik yang diterbitkan oleh Balai Besar Sertifikasi Elektronik (BSrE), Badan Siber dan Sandi Negara (BSSN). 2 / 6 2 / 6 3 b. Dikerjakan oleh tenaga profesional dari luar Perpustakaan Nasional RI dibuktikan dengan ijazah dan atau hal lain yang dapat membuktikan dapat dianggap layak secara keilmuan. c. Proses Alih Wahana harus memperhatikan Jenjang Pembaca yang menjadi sasaran pembaca, yaitu Pembaca Dini (A), Pembaca Awal (B), Pembaca Semenjana (C), Pembaca Madya (D), Pembaca Mahir (E). Level Pembaca Awal (B) sendiri dibagi ke dalam tiga subjenjang, yaitu level B-1, B-2, dan B-3. Dalam hal ini, jenjang yang menjadi sasaran adalah Pembaca Awal B3 dan Pembaca Semenjana (C).', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2510463);
