INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66080690', 66080690, 'analyze_legacy', 'Kementerian Kesehatan', 'central', 'SEKRETARIAT DIREKTORAT JENDERAL KESEHATAN LANJUTAN', 'Konstruksi Fisik - Pelaksanaan Pembangunan/Renovasi RSUD Kab. Kepulauan Mentawai  (RSUD Kepulauan Mentawai)', 'Pekerjaan Konstruksi', 'Tender', 'Sumatera Barat, Kepulauan Mentawai (Kab.)', 265801800000, 'March 2026', 'APBN - RUPIAH MURNI (A)', 0, 1, '( 1, PT, @ 248588000000 )', '1. konstruksi fisik ( 1, PT, @ 248588000000 ); Konstruksi fisik - Pelaksanaan Pembangunan Kab. Kepulauan Mentawai (RSUD Kepulauan Mentawai) Uraian pekerjaan meliputi pelaksanaan konstruksi terintegrasi rancang bangun (design and build) berupa penyusunan perencanaan teknis dan pelaksanaan pekerjaan konstruksi bangunan rumah sakit, termasuk pekerjaan struktur, arsitektur, mekanikal, elektrikal, dan plumbing (MEP), serta prasarana pendukung, dalam rangka peningkatan kelas rumah sakit dari Kelas D menjadi Kelas C. Pekerjaan dilaksanakan dalam satu kesatuan tanggung jawab penyedia hingga tercapai fungsi bangunan sesuai standar pelayanan rumah sakit.', 'Pekerjaan konstruksi terintegrasi rancang bangun (design and build) untuk pembangunan dan/atau renovasi bangunan rumah sakit dalam rangka peningkatan kelas rumah sakit dari Kelas D menjadi Kelas C. Ruang lingkup pekerjaan meliputi kegiatan perencanaan teknis dan pelaksanaan konstruksi dalam satu kesatuan tanggung jawab penyedia sesuai standar bangunan rumah sakit. Spesifikasi teknis dan Kerangka Acuan Kerja (KAK) secara rinci akan ditetapkan dan dijelaskan lebih lanjut dalam dokumen pemilihan/tender sesu