INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66039387', 66039387, 'analyze_legacy', 'Kementerian Kesehatan', 'central', 'BALAI KEKARANTINAAN KESEHATAN KELAS I KENDARI', 'Pengadaan Pakaian Dinas Harian Pegawai', 'Barang', 'E-Purchasing', 'Sulawesi Tenggara, Kendari (Kota)', 90209000, 'January 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '( 1 PT, @ 90209000 )', '1. Pengadaan Pakaian Dinas Harian Pegawai ( 1 PT, @ 90209000 );', '1. PAKAIAN DINAS HARIAN (PDH) PEGAWAI PRIA BENTUK, WARNA, DAN KELENGKAPAN : 1) Kemeja lengan pendek berbahan linen warna biru muda (pantone #A7D4F5) memakai lidah pundak dengan satu kancing dan kerah berdiri 2) Belahan depan polos dengan lima kancing, dua saku tempel bagian atas memakai tutup dan masing-masing memakai satu kancing 3) Celana panjang berbahan formal bahan (regular fit)/katun twill warna biru tua (pantone #000E28) dengan dua saku samping model miring dan dua saku belakang model bobok tanpa tutup 4) Sabuk kecil warna hitam, timang dengan dasar polos warna kuning emas berlogo BKK 2. PAKAIAN DINAS HARIAN (PDH) PEGAWAI PEREMPUAN 1) Kemeja lengan pendek/panjang berbahan linen warna biru muda (pantone #A7D4F5) memakai lidah pundak dengan satu kancing dan kerah berdiri 2) Belahan depan polos dengan lima kancing, dua saku tempel bagian atas memakai tutup dan masing-masing memakai satu kancing 3) Rok/celana panjang berbahan formal bahan (regular fit)/Katun Twill warna biru tua (Pantone #000E28) dengan dua saku samping model miring dan dua saku belakang model bobok tanpa tutup 4) Sabuk kecil warna hitam, timang dengan dasar polos warna kuning emas berlogo BKK. 3. PAKAIAN DINAS LAPANGAN (PDL) PEGAWAI PRIA/PEREMPUAN 1) Kemeja lengan panjang warna biru tua memakai lidah pundak dengan satu kancing 2) Terdapat tujuh kancing depan sepanjang badan, dengan saku pada sisi kanan dan kiri bagian depan dengan lidah penutup dan kancing dalam 3) Celana panjang model tactical warna cokelat tua 4) Terdapat saku pada sisi kiri dan kanan bagian atas celana dan saku (bobok) pada sisi belakang baik sisi kiri dan kanan 5) Terdapat lubang sabuk di pinggang', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2514320);
