INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66040320', 66040320, 'analyze_legacy', 'Kementerian Perencanaan Pembangunan Nasional', 'central', 'KANTOR MENTERI NEGARA PPN  BAPPENAS', 'Jasa Konsultan Junior Penyusunan Kajian Proyeksi Kontribusi PSN di Bidang Energi EBT terhadap Trisula Pembangunan Tahun Anggaran 2026', 'Jasa Konsultansi', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Pusat (Kota)', 97520400, 'February 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1 Paket Dokumen', 'menyediakan dukungan teknis dan analitis dalam pengumpulan dan pengolahan data, evaluasi kinerja pelaksanaan PSN, serta penyusunan proteksi kontribusi PSN energi EBT terhadap pencapaian Trisula Pembangunan di Indonesia. Kegiatan ini mencakup analisis koordinasi lintas pemangku kepentingan, identifikasi isu dan hambatan teknis maupun non-teknis, perbaikan guna meningkatkan efektivitas PSN di bidang EBT agar selaras dengan arah kebijakan pembangunan nasional, termasuk RPJMN 2025–2029', '1. minimal Sarjana (S1) di bidang Teknik Sipil atau disiplin ilmu yang setara, dengan pemahaman mengenai analisis sistem, perencanaan pembangunan, dan evaluasi program 2.memiliki pengalaman pekerjaan dengan karakteristik serupa, meliputi analisis teknis, kajian kebijakan, pemantauan proyek, atau evaluasi program lintas sektor dalam kurun waktu relevan, dibuktikan dengan data pada CV dan dokumen lain yang setara 3. Memiliki pengalaman koordinasi dengan K/L, pemerintah daerah, atau pemangku kepentingan terkait, khususnya dalam kegiatan pemantauan proyek atau proses perencanaan lintas sektor dibuktikan dengan surat tugas, notula/risalah rapat, atau dokumen kegiatan terkait 4. Mampu menyusun laporan analisis berbasis data yang mempertimbangkan aspek ekonomi, lingkungan, sosial, dan kontribusinya terhadap tujuan pembangunan berkelanjutan dibuktikan dengan surat keterangan kerja/surat referensi/ sertifikat', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2514893);
