INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66040317', 66040317, 'analyze_legacy', 'Kementerian Perencanaan Pembangunan Nasional', 'central', 'KANTOR MENTERI NEGARA PPN  BAPPENAS', 'Jasa Konsultan Junior Penyusunan Kajian Proyeksi Kontribusi Proyek Strategis Nasional (PSN) di Bidang Energi Migas dan Minerba terhadap Trisula Pembangunan Tahun Anggaran 2026', 'Jasa Konsultansi', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Pusat (Kota)', 97520400, 'February 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1 Paket Dokumen', 'menyusun proyeksi kontribusi PSN bidang energi migas dan minerba terhadap Trisula Pembangunan, menyediakan bahan masukan strategis berbasis data bagi proses koordinasi lintas sektor Deputi Bidang Pangan, Sumber Daya Alam, dan Lingkungan Hidup, serta menjadi bahan pertimbangan dalam perumusan kebijakan terkait PSN di bidang energi migas dan minerba.', '1. minimal Magister (S2) di bidang Teknik Industri atau disiplin ilmu yang setara, dengan pemahaman mengenai analisis sistem, perencanaan pembangunan, dan pendekatan berbasis data; 2. Memiliki pengalaman pekerjaan minimal dua (2) tahun dengan karakteristik serupa, meliputi analisis teknis, penyusunan proyeksi kontribusi, serta kajian lintas sektor dalam kurun waktu relevan, dibuktikan dengan data pada CV dan dokumen lain yang setara; 3. Memiliki pengalaman koordinasi dengan K/L, pemerintah daerah, atau pemangku kepentingan terkait, khususnya dalam kegiatan penyusunan kajian, pengolahan data proyeksi, atau proses perencanaan lintas sektor, dibuktikan dengan surat tugas, notula/risalah hasil rapat, atau dokumen kegiatan terkait; 4. Mampu 