INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66041980', 66041980, 'analyze_legacy', 'Kementerian Perencanaan Pembangunan Nasional', 'central', 'KANTOR MENTERI NEGARA PPN  BAPPENAS', 'Jasa Konsultan Penyusunan Kajian Pengembangan Tata Kelola Implementasi Ekonomi Sirkular (Circular Economy Governance Analyst)', 'Jasa Konsultansi', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Pusat (Kota)', 99900000, 'February 2026', 'APBN - HIBAH LUAR NEGERI (I)', 1, 1, '1 Paket Dokumen', 'mendukung penyusunan rancangan tata kelola implementasi ekonomi sirkular pada kegiatan Jasa Konsultan Firma Penguatan Kebijakan dan Perencanaan Terintegrasi Rendah Karbon, Berketahanan Iklim, Ekonomi Sirkular, dan Keanekaragaman Hayati di Tingkat Kota yang adaptif terhadap konteks perkotaan termasuk namun tidak terbatas pada; mekanisme koordinasi lintas sektor, peran dan pola kemitraan masing-masing stakeholder terkait pada 4 Kota Pilot SCIP (Palembang, Semarang, Balikpapan, dan Bitung)', '1. Pendidikan minimal sarjana (S-1) di bidang Teknik Lingkungan/Teknik Industri; 2. Memiliki kompetensi sesuai bidang yang dipersyaratkan dibuktikan dengan ijazah jenjang pendidikan, sertifikat keahlian/teknis, dan/atau sertifikat pelatihan/kursus; 3. Memiliki pengalaman kerja minimal 3 (tiga) tahun di bidang pemerintahan, dengan keterlibatan pada perencanaan pembangunan daerah, kebijakan publik, dan pengalaman teknis di bidang pengelolaan persampahan dan isu lingkungan, serta pemahaman mengenai hubungan lintas sektor di tingkat daerah menjadi nilai tambah; 4. Memiliki pengalaman dan pemahaman mengenai konsep pengelolaan sampah berkelanjutan, ekonomi sirkular dan pembangunan yang berwawasan lingkungan dan/atau pembangunan berkelanjutan yang dibuktikan dengan pengalaman bekerja di bidang tersebut yang tercantum dalam CV/referensi; 5. Memiliki keterampilan dalam analisis data serta cakap dalam presentasi dan penulisan laporan yang dibuktikan dengan pengalaman bekerja di dalam bidang tersebut yang tercantum dalam CV/referensi; 6. Memiliki kemampuan dan pengalaman dalam mengumpulkan dan mengolah data yang dihasilkan dari kegiatan Focus Group Discussion (FGD) dibuktikan melalui pengalaman kerja dalam CV/Referensi', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2516499);
