INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66086732', 66086732, 'analyze_legacy', 'Kab. Tasikmalaya', 'kabkota', 'Kecamatan Singaparna', 'Belanja Barang untuk Dijual/Diserahkan kepada Masyarakat', 'Barang', 'E-Purchasing', 'Jawa Barat, Tasikmalaya (Kab.)', 10000000, 'January 2026', 'APBD', 1, 1, '1 Paket', 'Hadiah;', 'Hadiah ;', 10000000, 'high', 'Pengadaan berupa "hadiah" untuk diserahkan kepada masyarakat tidak menunjukkan kebutuhan barang yang spesifik, manfaat publik yang terukur, atau keterkaitan yang jelas dengan fungsi pelayanan. Deskripsi yang sangat umum meningkatkan risiko belanja seremonial/konsumtif dan sulit diuji kewajarannya, sehingga seluruh nilai patut dicermati sebagai potensi pemborosan.', NULL, NULL, 3, 1, 1, 1, 1, 2519769);
